-- ============================================================================
-- communion.operation.moduleId 批量补全脚本 (增强版)
-- 模式: 临时表插入映射数据 + 连表 UPDATE (单事务原子)
-- 
-- 目标:
--   operation.moduleId 全部填充为【主ERP(system=1)的一级模块(level=1)】的 mid。
--   不关联移动端(system=2)/会计(system=3)的模块, 也不关联二级/三级深层模块。
--   PO 保留 module 强关联, 但数据层只指向主系统一级 module, 避免关联过深。
-- 
-- 数据来源:
--   依据 operation 字段(Action 方法名)的业务关键词, 归类到 19 个 system=1 且 level=1 的模块。
--   归类规则见 scripts/classify_module.py (1349 条全覆盖, 0 遗漏)。
-- 
-- 使用方式:
--   1. 先备份: mysqldump -t communion operation > operation_backup.sql
--   2. 执行本脚本(需可写库, 生产只读库无法执行)
--   3. 看末尾 SELECT 校验: empty_moduleId_count 应为 0, 分布表应合理
--   4. 确认无误后 COMMIT; 如需回滚, 把 COMMIT 改为 ROLLBACK 重新执行整段
-- ============================================================================

START TRANSACTION;

-- ---------- 0. system=1 且 level=1 强制校验 (执行前自检) ----------
-- 确认本脚本用到的 19 个 mid 在 module 表里都是 system=1(主ERP) 且 level=1(一级模块)
-- (期望返回 0 行; 若返回非 0 行, 说明 mid 指向了非主系统或深层模块, 请先核对)
SELECT mid, name, system, level AS unexpected
FROM communion.module
WHERE mid IN (1,2,4,5,6,7,8,9,10,134,203,204,227,228,237,240,316,338,457) AND (system <> 1 OR level <> 1);

-- ---------- 1. 执行前快照: 当前 moduleId 空值数 ----------
SELECT COUNT(*) AS empty_moduleId_before
FROM communion.operation
WHERE moduleId IS NULL OR moduleId = 0;

-- ---------- 2. 建临时表 ----------
DROP TEMPORARY TABLE IF EXISTS tmp_operation_module;
CREATE TEMPORARY TABLE tmp_operation_module (
    oid       INT NOT NULL PRIMARY KEY,
    moduleId  INT NOT NULL
) ENGINE=Memory;

