-- ---------- 4. 连表更新 operation.moduleId ----------
-- 仅更新临时表覆盖的 oid, 其余 operation 不受影响
UPDATE communion.operation o
    INNER JOIN tmp_operation_module t ON o.oid = t.oid
SET o.moduleId = t.moduleId;

-- ---------- 5. 执行后校验 ----------
-- 5.1 moduleId 为空的数量 (期望: 0)
SELECT COUNT(*) AS empty_moduleId_after
FROM communion.operation
WHERE moduleId IS NULL OR moduleId = 0;

-- 5.2 各一级模块 operation 数量分布 (关联 system=1 且 level=1 的模块名)
SELECT m.mid, m.name AS module_name, COUNT(o.oid) AS op_count
FROM communion.operation o
    INNER JOIN communion.module m ON o.moduleId = m.mid
WHERE m.system = 1 AND m.level = 1
GROUP BY m.mid, m.name
ORDER BY op_count DESC;

-- ---------- 6. 清理临时表 ----------
DROP TEMPORARY TABLE IF EXISTS tmp_operation_module;

-- 确认无误后提交; 如需回滚, 把下一行改为 ROLLBACK 后重新执行整段
COMMIT;
